from __future__ import annotations

import argparse
from pathlib import Path

from .constraint_emitter import emit_constraints
from .ddl_emitter import BUILD_FOLDERS, emit_tables, ensure_output_dirs
from .index_emitter import emit_indexes
from .model_loader import load_model
from .staging_emitter import emit_staging
from .validate import validate_or_exit
from .view_emitter import emit_views


def _write_build_all(out: Path) -> None:
    lines = [
        "-- Generated by tools.generator. Do not hand-edit.",
        "--",
        "-- Run from this directory: the :r includes are resolved against the current",
        "-- working directory, not the script's location.",
        "--   sqlcmd -S <server> -b -i build_all.sql -v DatabaseName=\"WidestWarehouse\"",
        "--",
        "-- DatabaseName is required. It is not :setvar here on purpose: a :setvar in the",
        "-- script would override the -v value and make the target database unchangeable.",
        ":ON ERROR EXIT",
        "",
    ]
    for folder in BUILD_FOLDERS:
        for file in sorted((out / folder).glob("*.sql"), key=lambda p: p.name.lower()):
            rel = file.relative_to(out)
            lines.append(f":r ./{rel.as_posix()}")
    (out / "build_all.sql").write_text("\n".join(lines) + "\n", encoding="utf-8", newline="\n")


def emit(args: argparse.Namespace) -> None:
    model = load_model(args.model)
    validate_or_exit(model)
    out = Path(args.out)
    ensure_output_dirs(out)
    emit_tables(model, out)
    emit_constraints(model, out)
    emit_indexes(model, out)
    emit_views(model, out)
    emit_staging(model, out)
    _write_build_all(out)
    print(f"Emitted {len(model.tables)} base tables to {out}")


def validate(args: argparse.Namespace) -> None:
    model = load_model(args.model)
    validate_or_exit(model)
    print(f"Validation passed ({len(model.tables)} base tables)")


def stats(args: argparse.Namespace) -> None:
    model = load_model(args.model)
    counts: dict[str, int] = {}
    for table in model.tables:
        counts[table.schema] = counts.get(table.schema, 0) + 1
        if (table.kind == "dim" and table.scd == "type2") or table.kind in {"bridge", "fact"}:
            counts["stg"] = counts.get("stg", 0) + 1
    for schema in sorted(counts):
        print(f"{schema}: {counts[schema]}")
    print(f"total: {sum(counts.values())}")


def main(argv: list[str] | None = None) -> None:
    parser = argparse.ArgumentParser(prog="python -m tools.generator.cli")
    parser.add_argument("--model", default="model")
    sub = parser.add_subparsers(dest="command", required=True)

    emit_p = sub.add_parser("emit")
    emit_p.add_argument("--out", default="sql")
    emit_p.set_defaults(func=emit)

    val_p = sub.add_parser("validate")
    val_p.set_defaults(func=validate)

    stats_p = sub.add_parser("stats")
    stats_p.set_defaults(func=stats)

    args = parser.parse_args(argv)
    args.func(args)


if __name__ == "__main__":
    main()
